sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionadoAdj = null;
  $scope.dadosVisiveisAdj = null;
  $scope.isFadingAdj = false;

  function carregarDadosAdj(ano) {
    $scope.isFadingAdj = true;

    $timeout(function() {
      var params = {};
      if (ano) {
        params.filtro_ano = ano;
      }

      spUtil.get('rcl_ajustado_card_1', params).then(function(response) {
        if (response.data && response.data.dadosAdj && response.data.dadosAdj.length > 0) {
          $scope.dadosVisiveisAdj = response.data.dadosAdj[0];
          $scope.anoSelecionadoAdj = $scope.dadosVisiveisAdj.anoAdj;
        } else {
          $scope.dadosVisiveisAdj = null;
          $scope.anoSelecionadoAdj = null;
        }

        $timeout(function() {
          $scope.isFadingAdj = false;
        }, 50);
      });
    }, 500);
  }

  carregarDadosAdj(null);

  $rootScope.$on('anoSelecionado', function(evt, ano) {
    carregarDadosAdj(ano);
  });
}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

/* --- Wrapper Principal (Animação e Layout) --- */
.financial-widget-wrapper {
  font-family: 'Roboto Flex', sans-serif;
  margin-top: 4rem; /* Alinhamento padrão */

  /* Lógica de Transição */
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

.financial-widget-wrapper.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

/* --- Estrutura Visual do Widget --- */
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  background-color: #fff;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
  font-family: 'Roboto Flex', sans-serif;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
  font-family: 'Roboto Flex', sans-serif;
}

/* Estilo para mensagem de "Nenhum dado" */
.indicator-value.small-text {
  font-size: 18px;
  color: #666;
  line-height: 1.5;
  padding: 20px;
}

/* --- Responsividade --- */
@media (max-width: 767px) {
  .financial-widget-wrapper {
    margin-top: 1rem;
  }
  .indicator-value {
    font-size: 24px;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .financial-widget-wrapper {
    margin-top: 2rem;
  }
}

@media (max-width: 350px) {
  .indicator-header {
    font-size: 12px;
  }
  .indicator-value {
    font-size: 20px;
    padding: 6px;
  }
}

