	 function formatarNumero(valor) {
  if (typeof valor !== 'number') {
    valor = parseFloat(valor);
  }

  return valor.toFixed(2) // fixa duas casas decimais
              .replace('.', ',') // troca ponto decimal por vírgula
              .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // separador de milhar
}


  var anoFiltradoAdj = input && input.filtro_ano ? input.filtro_ano : null;

  if (!anoFiltradoAdj) {
    var grAnoAdj = new GlideRecord('x_sded9_portal_t_0_u_rreo');
    grAnoAdj.orderByDesc('u_ano');
    grAnoAdj.setLimit(1);
    grAnoAdj.query();

    if (!grAnoAdj.next()) {
      data.temDadoAdj = false;
      data.anoAdj = null;
      data.dadosAdj = [];
      return;
    }

    anoFiltradoAdj = grAnoAdj.getValue('u_ano');
  }

  var grSomaAdj = new GlideRecord('x_sded9_portal_t_0_u_rreo');
  grSomaAdj.addQuery('u_ano', anoFiltradoAdj);
  grSomaAdj.query();

  var somaAdj = 0;
  while (grSomaAdj.next()) {
    somaAdj += parseFloat(grSomaAdj.getValue('adjusted_rreo_fiscal_management_report_2')) || 0;
  }

  if (somaAdj > 0) {
    //var valorFormatadoAdj = (somaAdj >= 1000000000) ? formatarNumeroAdj(somaAdj, 1000000000, 'BI') : formatarNumeroAdj(somaAdj, 1000000, 'MI');
		var valorFormatadoAdj = formatarNumero(somaAdj, 1, '');
    data.temDadoAdj = true;
    data.valorSomaAdj = somaAdj;
    data.valorSomaFormatadoAdj = valorFormatadoAdj;
    data.anoAdj = anoFiltradoAdj;
    data.dadosAdj = [{
      anoAdj: anoFiltradoAdj,
      valorSomaAdj: somaAdj,
      valorSomaFormatadoAdj: valorFormatadoAdj,
      temDadoAdj: true
    }];
  } else {
    data.temDadoAdj = false;
    data.anoAdj = anoFiltradoAdj;
    data.dadosAdj = [{
      anoAdj: anoFiltradoAdj,
      valorSomaAdj: 0,
      valorSomaFormatadoAdj: '0',
      temDadoAdj: false
    }];
  }
})();
